1	//! The single send fallback for a forced tool choice that the service rejects.
2	//!
3	//! An Anthropic model on Bedrock can reject a forced tool choice
4	//! (`toolChoice` `any` or `tool`) with a `ValidationException`. When the
5	//! first request carried a forced choice and the service rejects it before
6	//! the stream starts, the provider sends one native request, which is a
7	//! different request, on the structured-output path. The handle then records the rejection, and
8	//! all later requests on the handle use the native path at once.
9	//!
10	//! This fallback does not break ADR-10 (*No silent auto-retry inside the
11	//! loop*), for four reasons. The fallback sends a *different* request, not
12	//! the same request again. It occurs at most once for each request. It is
13	//! logged. It never follows a transient error (throttling, a 5xx error or a
14	//! transport error): those errors go to the caller unchanged.
15	//!
16	//! The match on the error text is a weak contract. If Bedrock changes the
17	//! text, the result is the same `ValidationException` as before this
18	//! fallback existed. The static model-id rule still sends the known models
19	//! on the native path from the first request.
20	
21	use std::future::Future;
22	
23	use paigasus_helikon_core::ModelError;
24	
25	use crate::error::SendFailure;
26	use crate::family::ModelFamily;
27	use crate::policy::{ForcedChoicePolicy, OutputPath};
28	use crate::translate::PreparedConverse;
29	
30	/// The output of a send, with the `synthesizing` value of the request that
31	/// was actually sent.
32	#[derive(Debug)]
33	pub(crate) struct Sent<T> {
34	    /// The output of the send.
35	    pub(crate) output: T,
36	    /// `synthesizing` of the request that was sent.
37	    pub(crate) synthesizing: bool,
38	    /// `true` when the request that was sent used native structured output.
39	    pub(crate) native: bool,
40	}
41	
42	/// Send `first`. If the service rejects its forced tool choice, send the
43	/// request again on the native path, one time.
44	///
45	/// The fallback occurs only when all of these conditions are true:
46	/// the model family is Anthropic, `first` carried a forced tool choice, and
47	/// the failure is a rejection of that choice. `rebuild` makes the native
48	/// request. An error from the second send goes to the caller with no
49	/// further fallback.
50	pub(crate) async fn send_with_fallback<T, B, S, Fut>(
51	    policy: &ForcedChoicePolicy,
52	    model_id: &str,
53	    first: PreparedConverse,
54	    rebuild: B,
55	    mut send: S,
56	) -> Result<Sent<T>, ModelError>
57	where
58	    B: FnOnce(OutputPath) -> Result<PreparedConverse, ModelError>,
59	    S: FnMut(PreparedConverse) -> Fut,
60	    Fut: Future<Output = Result<T, SendFailure>>,
61	{
62	    for n in &first.notices {
63	        policy.note(*n, model_id);
64	    }
65	    let synthesizing = first.synthesizing;
66	    let native = first.output_config.is_some();
67	    let first_was_forced = first.has_forced_tool_choice();
68	
69	    let failure = match send(first).await {
70	        Ok(output) => {
71	            return Ok(Sent {
72	                output,
73	                synthesizing,
74	                native,
75	            })
76	        }
77	        Err(f) => f,
78	    };
79	
80	    if !(policy.family() == ModelFamily::Anthropic
81	        && first_was_forced
82	        && failure.forced_choice_rejected)
83	    {
84	        return Err(failure.error);
85	    }
86	
87	    if policy.record_rejection() {
88	        tracing::warn!(
89	            target: "paigasus::bedrock::model",
90	            model_id = %model_id,
91	            "the model rejected a forced tool choice; native structured output is now in use for this handle"
92	        );
93	    }
94	
95	    let second = rebuild(OutputPath::Native)?;
96	    for n in &second.notices {
97	        policy.note(*n, model_id);
98	    }
99	    let synthesizing = second.synthesizing;
100	    let native = second.output_config.is_some();
101	    match send(second).await {
102	        Ok(output) => Ok(Sent {
103	            output,
104	            synthesizing,
105	            native,
106	        }),
107	        Err(f) => Err(f.error),
108	    }
109	}
110	
111	#[cfg(test)]
112	mod tests {
113	    use super::*;
114	    use std::collections::VecDeque;
115	    use std::sync::{Arc, Mutex};
116	
117	    use paigasus_helikon_core::{ContentPart, Item, ModelError, ModelRequest, ResponseFormat};
118	    use serde_json::{json, Value};
119	
120	    use crate::builder::{offline_config, Config};
121	    use crate::error::SendFailure;
122	    use crate::family::ModelFamily;
123	    use crate::policy::{ForcedChoicePolicy, OutputPath};
124	    use crate::translate::tools::SYNTHESIZED_TOOL_NAME;
125	    use crate::translate::{build_request, to_wire_json};
126	
127	    const CLAUDE: &str = "anthropic.claude-3-5-sonnet-20241022-v2:0";
128	    const MISTRAL: &str = "mistral.mistral-large-2407-v1:0";
129	
130	    fn rejected() -> SendFailure {
131	        SendFailure {
132	            forced_choice_rejected: true,
133	            error: ModelError::Other(anyhow::anyhow!(
134	                "bedrock ValidationException: This model doesn't support the toolConfig.toolChoice.any field."
135	            )),
136	        }
137	    }
138	
139	    fn transaction_request() -> ModelRequest {
140	        let mut req = ModelRequest::new();
141	        req.messages = vec![Item::UserMessage {
142	            content: vec![ContentPart::Text {
143	                text: "Coffee, 4.50 EUR".to_owned(),
144	            }],
145	        }];
146	        req.model_settings.response_format = Some(ResponseFormat::JsonSchema {
147	            name: "Transaction".to_owned(),
148	            schema: json!({
149	                "type": "object",
150	                "properties": {
151	                    "amount": {"type": "number"},
152	                    "currency": {"type": "string"},
153	                },
154	                "required": ["amount", "currency"]
155	            }),
156	            strict: false,
157	        });
158	        req
159	    }
160	
161	    fn text_request() -> ModelRequest {
162	        let mut req = ModelRequest::new();
163	        req.messages = vec![Item::UserMessage {
164	            content: vec![ContentPart::Text {
165	                text: "Hello".to_owned(),
166	            }],
167	        }];
168	        req
169	    }
170	
171	    /// Run `send_with_fallback` with a scripted fake send. Returns the result
172	    /// and the wire projection of each request that the fake received.
173	    fn drive(
174	        policy: &ForcedChoicePolicy,
175	        cfg: &Config,
176	        req: &ModelRequest,
177	        script: Vec<Result<(), SendFailure>>,
178	    ) -> (Result<Sent<()>, ModelError>, Vec<Value>) {
179	        let first = build_request(cfg, req, policy.path()).expect("first request");
180	        let sent: Arc<Mutex<Vec<Value>>> = Arc::new(Mutex::new(Vec::new()));
181	        let script = Arc::new(Mutex::new(VecDeque::from(script)));
182	        let send = {
183	            let sent = sent.clone();
184	            let script = script.clone();
185	            move |p: crate::translate::PreparedConverse| {
186	                sent.lock().unwrap().push(to_wire_json(&p));
187	                let next = script
188	                    .lock()
189	                    .unwrap()
190	                    .pop_front()
191	                    .expect("a send that the script does not cover");
192	                async move { next }
193	            }
194	        };
195	        let rt = tokio::runtime::Builder::new_current_thread()
196	            .enable_all()
197	            .build()
198	            .expect("tokio runtime");
199	        let result = rt.block_on(send_with_fallback(
200	            policy,
201	            &cfg.model_id,
202	            first,
203	            |path| build_request(cfg, req, path),
204	            send,
205	        ));
206	        let wires = sent.lock().unwrap().clone();
207	        (result, wires)
208	    }
209	
210	    fn assert_forced(wire: &Value) {
211	        assert_eq!(
212	            wire["toolConfig"]["toolChoice"],
213	            json!({"tool": {"name": SYNTHESIZED_TOOL_NAME}}),
214	            "{wire:#}"
215	        );
216	    }
217	
218	    fn assert_native(wire: &Value) {
219	        assert!(!wire["outputConfig"].is_null(), "{wire:#}");
220	        assert!(wire["toolConfig"].is_null(), "{wire:#}");
221	    }
222	
223	    #[test]
224	    fn rejection_falls_back_once_to_native() {
225	        let cfg = offline_config(CLAUDE);
226	        let policy = ForcedChoicePolicy::without_static_rule(ModelFamily::Anthropic);
227	        let (res, wires) = drive(
228	            &policy,
229	            &cfg,
230	            &transaction_request(),
231	            vec![Err(rejected()), Ok(())],
232	        );
233	        assert_eq!(wires.len(), 2);
234	        assert_forced(&wires[0]);
235	        assert_native(&wires[1]);
236	        assert_eq!(policy.path(), OutputPath::Native);
237	        assert!(res.is_ok());
238	    }
239	
240	    #[test]
241	    fn second_request_on_same_handle_goes_native_at_once() {
242	        let cfg = offline_config(CLAUDE);
243	        let policy = ForcedChoicePolicy::without_static_rule(ModelFamily::Anthropic);
244	        let req = transaction_request();
245	        let (res, _) = drive(&policy, &cfg, &req, vec![Err(rejected()), Ok(())]);
246	        assert!(res.is_ok());
247	        let (res, wires) = drive(&policy, &cfg, &req, vec![Ok(())]);
248	        assert!(res.is_ok());
249	        assert_eq!(wires.len(), 1);
250	        assert_native(&wires[0]);
251	    }
252	
253	    #[test]
254	    fn non_anthropic_family_does_not_fall_back() {
255	        let cfg = offline_config(MISTRAL);
256	        let policy = ForcedChoicePolicy::without_static_rule(ModelFamily::Mistral);
257	        let (res, wires) = drive(&policy, &cfg, &transaction_request(), vec![Err(rejected())]);
258	        assert_eq!(wires.len(), 1);
259	        assert_forced(&wires[0]);
260	        assert!(res.is_err());
261	        assert_eq!(policy.path(), OutputPath::ForcedTool);
262	    }
263	
264	    #[test]
265	    fn other_errors_do_not_fall_back() {
266	        let cfg = offline_config(CLAUDE);
267	        let policy = ForcedChoicePolicy::without_static_rule(ModelFamily::Anthropic);
268	        let (res, wires) = drive(
269	            &policy,
270	            &cfg,
271	            &transaction_request(),
272	            vec![Err(SendFailure {
273	                forced_choice_rejected: false,
274	                error: ModelError::RateLimited {
275	                    retry_after_ms: Some(1000),
276	                },
277	            })],
278	        );
279	        assert_eq!(wires.len(), 1);
280	        assert!(matches!(
281	            res,
282	            Err(ModelError::RateLimited {
283	                retry_after_ms: Some(1000)
284	            })
285	        ));
286	        assert_eq!(policy.path(), OutputPath::ForcedTool);
287	    }
288	
289	    #[test]
290	    fn second_rejection_is_returned() {
291	        let cfg = offline_config(CLAUDE);
292	        let policy = ForcedChoicePolicy::without_static_rule(ModelFamily::Anthropic);
293	        let (res, wires) = drive(
294	            &policy,
295	            &cfg,
296	            &transaction_request(),
297	            vec![Err(rejected()), Err(rejected())],
298	        );
299	        assert_eq!(wires.len(), 2);
300	        assert!(matches!(res, Err(ModelError::Other(_))));
301	        assert_eq!(policy.path(), OutputPath::Native);
302	    }
303	
304	    #[test]
305	    fn request_without_forced_choice_does_not_fall_back() {
306	        let cfg = offline_config(CLAUDE);
307	        let policy = ForcedChoicePolicy::without_static_rule(ModelFamily::Anthropic);
308	        let (res, wires) = drive(&policy, &cfg, &text_request(), vec![Err(rejected())]);
309	        assert_eq!(wires.len(), 1);
310	        assert!(res.is_err());
311	        assert_eq!(policy.path(), OutputPath::ForcedTool);
312	    }
313	
314	    #[test]
315	    fn fallback_returns_synthesizing_of_the_sent_request() {
316	        let cfg = offline_config(CLAUDE);
317	        let policy = ForcedChoicePolicy::without_static_rule(ModelFamily::Anthropic);
318	        let (res, wires) = drive(
319	            &policy,
320	            &cfg,
321	            &transaction_request(),
322	            vec![Err(rejected()), Ok(())],
323	        );
324	        assert_eq!(wires[0]["synthesizing"], json!(true));
325	        let sent = res.expect("the fallback send succeeds");
326	        assert!(!sent.synthesizing);
