1	//! Model capability flags for Bedrock model families.
2	//!
3	//! The `structured_output` flag is set for the families that support a forced
4	//! tool choice or native output. Claude Sonnet 5.5 and Claude Opus 5.5 reject a
5	//! forced tool choice and use native output (`outputConfig`). On these models
6	//! `ResponseFormat::JsonObject` degrades to text.
7	//!
8	//! Returns conservative defaults for unknown families; callers may override
9	//! via [`crate::BedrockModelBuilder::capabilities`].
10	
11	use crate::family::ModelFamily;
12	use paigasus_helikon_core::ModelCapabilities;
13	
14	/// Return the capability flags for a family.
15	///
16	/// The `structured_output` flag is set for families that support a forced
17	/// tool choice or native output. A forced tool choice synthesizes structured
18	/// output on most models. Claude Sonnet 5.5 and Claude Opus 5.5 use native
19	/// output (`outputConfig`) instead, and `ResponseFormat::JsonObject` degrades
20	/// to text there.
21	/// No per-family `max_output_tokens` default is returned; omitting
22	/// `inferenceConfig.maxTokens` lets the model apply its own correct default,
23	/// which avoids `ValidationException` on models whose limit is below any
24	/// hardcoded value.  Callers may supply an explicit default via
25	/// [`crate::BedrockModelBuilder::max_output_tokens_default`].
26	pub(crate) fn caps_for(family: ModelFamily) -> ModelCapabilities {
27	    match family {
28	        ModelFamily::Anthropic => ModelCapabilities::empty()
29	            .with_streaming()
30	            .with_tools()
31	            .with_parallel_tool_calls()
32	            .with_structured_output(),
33	        ModelFamily::AmazonNova => ModelCapabilities::empty()
34	            .with_streaming()
35	            .with_tools()
36	            .with_parallel_tool_calls()
37	            .with_structured_output(),
38	        ModelFamily::AmazonTitan => ModelCapabilities::empty().with_streaming().with_tools(),
39	        ModelFamily::Llama => ModelCapabilities::empty().with_streaming().with_tools(),
40	        ModelFamily::Mistral => ModelCapabilities::empty()
41	            .with_streaming()
42	            .with_tools()
43	            .with_parallel_tool_calls()
44	            .with_structured_output(),
45	        ModelFamily::Cohere => ModelCapabilities::empty().with_streaming().with_tools(),
46	        ModelFamily::Unknown => ModelCapabilities::empty().with_streaming().with_tools(),
47	    }
48	}
