294	/// Translate a core [`ToolChoice`] into a Bedrock [`BedrockToolChoice`].
295	///
296	/// Returns `None` when the family does not support forced tool choice (the
297	/// `tool_choice` field is omitted from the request). `ToolChoice::None` is
298	/// handled before this function is called (it suppresses `toolConfig` entirely).
299	fn translate_tool_choice(tc: &ToolChoice, family: ModelFamily) -> Option<BedrockToolChoice> {
300	    match tc {
301	        ToolChoice::Auto => Some(BedrockToolChoice::Auto(AutoToolChoice::builder().build())),
302	        ToolChoice::Required => {
303	            if !family.supports_forced_tool_choice() {
304	                tracing::debug!(
305	                    target: "paigasus::bedrock::translate",
306	                    ?family,
307	                    "ToolChoice::Required requested but family does not support forced tool choice; omitting",
308	                );
309	                return None;
310	            }
311	            Some(BedrockToolChoice::Any(AnyToolChoice::builder().build()))
312	        }
313	        ToolChoice::None => {
314	            // ToolChoice::None is handled early in build_request; unreachable here.
315	            None
316	        }
317	        ToolChoice::Tool { name } => {
318	            if !family.supports_forced_tool_choice() {
319	                tracing::debug!(
320	                    target: "paigasus::bedrock::translate",
321	                    ?family,
322	                    tool = %name,
323	                    "ToolChoice::Tool requested but family does not support forced tool choice; omitting",
324	                );
325	                return None;
326	            }
327	            match SpecificToolChoice::builder().name(name).build() {
328	                Ok(s) => Some(BedrockToolChoice::Tool(s)),
329	                Err(e) => {
330	                    tracing::warn!(
331	                        target: "paigasus::bedrock::translate",
332	                        err = %e,
333	                        "failed to build SpecificToolChoice; omitting tool_choice",
334	                    );
335	                    None
336	                }
337	            }
338	        }
339	        _ => {
340	            tracing::debug!(
341	                target: "paigasus::bedrock::translate",
342	                "unknown ToolChoice variant; omitting",
343	            );
344	            None
345	        }
346	    }
347	}
