1	//! Translation layer between the Paigasus core types and Bedrock Converse API types.
2	
3	pub mod schema;
4	
5	mod native;
6	pub(crate) mod native_schema;
7	pub(crate) mod request;
8	pub(crate) mod response_format;
9	pub(crate) mod tools;
10	
11	use aws_sdk_bedrockruntime::types::{
12	    AnyToolChoice, AutoToolChoice, InferenceConfiguration, Message, OutputConfig,
13	    SpecificToolChoice, SystemContentBlock, Tool, ToolChoice as BedrockToolChoice,
14	    ToolConfiguration,
15	};
16	use paigasus_helikon_core::{ModelError, ModelRequest, ToolChoice};
17	
18	use crate::builder::Config;
19	use crate::family::ModelFamily; // used by translate_tool_choice
20	use crate::policy::{NativeNotice, OutputPath};
21	use crate::translate::request::items_to_messages;
22	use crate::translate::response_format::{synthesize, Synthesized};
23	use crate::translate::schema::Ruleset;
24	use crate::translate::tools::tool_specs;
25	
26	/// A fully-assembled Bedrock Converse request, ready to send.
27	///
28	/// The fields map onto the Bedrock SDK `converse` / `converse_stream` input
29	/// parameters. Callers should inspect `synthesizing` to decide how to route
30	/// stream events (synthesized structured output → `TokenDelta` remapping).
31	#[derive(Debug)]
32	pub(crate) struct PreparedConverse {
33	    /// Bedrock model identifier (may include cross-region profile prefix).
34	    pub(crate) model_id: String,
35	    /// System prompt blocks.
36	    pub(crate) system: Vec<SystemContentBlock>,
37	    /// Conversation turns. Adjacent same-role turns are joined.
38	    pub(crate) messages: Vec<Message>,
39	    /// Tool configuration (tools list + optional tool_choice).
40	    pub(crate) tool_config: Option<ToolConfiguration>,
41	    /// Base inference parameters.
42	    pub(crate) inference_config: Option<InferenceConfiguration>,
43	    /// Whether the stream translator should remap the synthesized tool's
44	    /// output to `TokenDelta`.
45	    pub(crate) synthesizing: bool,
46	    /// Native structured-output configuration. Only the native path sets it.
47	    pub(crate) output_config: Option<OutputConfig>,
48	    /// The changes of meaning that the native path made to the request.
49	    /// The forced-tool path always leaves this empty.
50	    pub(crate) notices: Vec<NativeNotice>,
51	}
52	
53	impl PreparedConverse {
54	    /// Returns `true` when the tool configuration forces a tool call
55	    /// (`toolChoice` is `any` or `tool`).
56	    pub(crate) fn has_forced_tool_choice(&self) -> bool {
57	        matches!(
58	            self.tool_config
59	                .as_ref()
60	                .and_then(ToolConfiguration::tool_choice),
61	            Some(BedrockToolChoice::Any(_) | BedrockToolChoice::Tool(_))
62	        )
63	    }
64	}
65	
66	/// The error for `ToolChoice::Required` when the tool list is empty.
67	fn required_without_tools_error() -> ModelError {
68	    ModelError::Other(anyhow::anyhow!(
69	        "ToolChoice::Required requires at least one tool to be defined",
70	    ))
71	}
72	
73	/// Make sure that `name` is the name of a tool in `tools`.
74	///
75	/// # Errors
76	/// Returns [`ModelError::Other`] when no tool in `tools` has the name `name`.
77	fn check_tool_name(tools: &[Tool], name: &str) -> Result<(), ModelError> {
78	    let defined = tools
79	        .iter()
80	        .any(|t| matches!(t, Tool::ToolSpec(spec) if spec.name() == name));
81	    if defined {
82	        Ok(())
83	    } else {
84	        Err(ModelError::Other(anyhow::anyhow!(
85	            "ToolChoice::Tool references tool {:?} which is not defined in the tool list",
86	            name,
87	        )))
88	    }
89	}
90	
91	/// Assemble the [`ToolConfiguration`] from the tool list and the optional tool choice.
92	///
93	/// Returns `None` when `tools` is empty. A `tool_choice` with no tools is then
94	/// omitted, because a `ToolConfiguration` needs at least one tool.
95	///
96	/// # Errors
97	/// Returns [`ModelError::Other`] when the SDK builder fails.
98	fn assemble_tool_config(
99	    tools: Vec<Tool>,
100	    tool_choice: Option<BedrockToolChoice>,
101	) -> Result<Option<ToolConfiguration>, ModelError> {
102	    if tools.is_empty() {
103	        if tool_choice.is_some() {
104	            tracing::debug!(
105	                target: "paigasus::bedrock::translate",
106	                "tool_choice requested but no tools provided; omitting ToolConfiguration",
107	            );
108	        }
109	        return Ok(None);
110	    }
111	    let mut builder = ToolConfiguration::builder();
112	    for t in tools {
113	        builder = builder.tools(t);
114	    }
115	    if let Some(tc) = tool_choice {
116	        builder = builder.tool_choice(tc);
117	    }
118	    Ok(Some(builder.build().map_err(|e| {
119	        ModelError::Other(anyhow::anyhow!("failed to build ToolConfiguration: {e}"))
120	    })?))
121	}
122	
123	/// Build an [`InferenceConfiguration`] from per-request settings and the builder config.
124	///
125	/// `maxTokens` is set only when the caller explicitly provided
126	/// `max_output_tokens` on the request or the builder was configured with
127	/// [`crate::BedrockModelBuilder::max_output_tokens_default`]. Omitting
128	/// `maxTokens` lets each Bedrock model apply its own correct default, which
129	/// avoids `ValidationException` on models whose limit is below any hardcoded
130	/// value.
131	///
132	/// Returns `None` when all three fields (temperature, top_p, max_tokens) are
133	/// absent — Bedrock accepts a missing `inferenceConfig` and all its fields are
134	/// individually optional.
135	fn build_inference_config(req: &ModelRequest, cfg: &Config) -> Option<InferenceConfiguration> {
136	    let max_tokens = req
137	        .model_settings
138	        .max_output_tokens
139	        .or(cfg.max_output_default);
140	
141	    // When no inference field is set, omit the config block entirely.
142	    if req.model_settings.temperature.is_none()
143	        && req.model_settings.top_p.is_none()
144	        && max_tokens.is_none()
145	    {
146	        return None;
147	    }
148	
149	    let mut b = InferenceConfiguration::builder();
150	    if let Some(t) = req.model_settings.temperature {
151	        b = b.temperature(t);
152	    }
153	    if let Some(p) = req.model_settings.top_p {
154	        b = b.top_p(p);
155	    }
156	    if let Some(mt) = max_tokens {
157	        b = b.max_tokens(mt as i32);
158	    }
159	    Some(b.build())
160	}
161	
162	/// Assemble a [`PreparedConverse`] from the builder `Config` and a [`ModelRequest`].
163	///
164	/// `path` selects the wire path. On [`OutputPath::Native`] the request goes to
165	/// the native builder, which sends structured output in `outputConfig` and
166	/// never forces a tool choice. The errors below are for
167	/// [`OutputPath::ForcedTool`].
168	///
169	/// # Errors
170	/// - Reserved tool name (`__paigasus_structured_output__` used by the caller).
171	/// - `ResponseFormat::JsonSchema`/`JsonObject` combined with `ToolChoice::Tool` (conflict).
172	/// - `ResponseFormat::JsonSchema`/`JsonObject` combined with `ToolChoice::None` (conflict).
173	/// - No message with content after empty/whitespace-only text is dropped.
174	/// - The last user message had only empty/whitespace-only text and the request would end with an assistant message.
175	pub(crate) fn build_request(
176	    cfg: &Config,
177	    req: &ModelRequest,
178	    path: OutputPath,
179	) -> Result<PreparedConverse, ModelError> {
180	    if path == OutputPath::Native {
181	        return native::build_native(cfg, req);
182	    }
183	    let family = cfg.family;
184	    let ruleset = Ruleset::for_family(family);
185	
186	    // Guard: ResponseFormat::JsonSchema / JsonObject + ToolChoice::Tool → conflict.
187	    let synthesizing_rf = matches!(
188	        req.model_settings.response_format.as_ref(),
189	        Some(paigasus_helikon_core::ResponseFormat::JsonSchema { .. })
190	            | Some(paigasus_helikon_core::ResponseFormat::JsonObject),
191	    );
192	    let forced_tool = matches!(
193	        req.model_settings.tool_choice.as_ref(),
194	        Some(ToolChoice::Tool { .. }),
195	    );
196	    if synthesizing_rf && family.supports_forced_tool_choice() && forced_tool {
197	        return Err(ModelError::Other(anyhow::anyhow!(
198	            "ResponseFormat::JsonSchema/JsonObject and ToolChoice::Tool are mutually \
199	             exclusive on Bedrock — use one or the other",
200	        )));
201	    }
202	
203	    // Guard: ResponseFormat::JsonSchema / JsonObject + ToolChoice::None → conflict.
204	    // Synthesis requires injecting a tool; ToolChoice::None suppresses toolConfig entirely.
205	    let none_choice = matches!(
206	        req.model_settings.tool_choice.as_ref(),
207	        Some(ToolChoice::None),
208	    );
209	    if synthesizing_rf && family.supports_forced_tool_choice() && none_choice {
210	        return Err(ModelError::Other(anyhow::anyhow!(
211	            "ResponseFormat::JsonSchema/JsonObject and ToolChoice::None are mutually \
212	             exclusive on Bedrock — structured-output synthesis requires a tool call",
213	        )));
214	    }
215	
216	    // ToolChoice::None means the model MUST NOT call any tool this turn.
217	    // Omit toolConfig entirely (do not send user tools either).
218	    if none_choice {
219	        let translated = items_to_messages(&req.messages)?;
220	        let inference_config = build_inference_config(req, cfg);
221	        return Ok(PreparedConverse {
222	            model_id: cfg.model_id.clone(),
223	            system: translated.system,
224	            messages: translated.messages,
225	            tool_config: None,
226	            inference_config,
227	            synthesizing: false,
228	            output_config: None,
229	            notices: Vec::new(),
230	        });
231	    }
232	
233	    // Translate messages.
234	    let translated = items_to_messages(&req.messages)?;
235	
236	    // Translate user tool defs (also validates reserved name).
237	    let user_specs = tool_specs(&req.tools, ruleset)?;
238	
239	    // Synthesize structured output tool (if applicable).
240	    let Synthesized {
241	        tool: synth_tool,
242	        tool_choice: synth_tc,
243	        synthesizing,
244	    } = synthesize(req.model_settings.response_format.as_ref(), family, ruleset)?;
245	
246	    // Merge tool lists: user tools first, synthesized appended.
247	    let mut all_tools: Vec<Tool> = user_specs.into_iter().map(Tool::ToolSpec).collect();
248	    if let Some(st) = synth_tool {
249	        all_tools.push(Tool::ToolSpec(st));
250	    }
251	
252	    // Build ToolConfiguration (only when there are tools or a tool_choice).
253	    let caller_tc = req
254	        .model_settings
255	        .tool_choice
256	        .as_ref()
257	        .and_then(|tc| translate_tool_choice(tc, family));
258	
259	    // Synthesis overrides caller tool_choice.
260	    // synth_tool.is_some() always pushes to all_tools above, so a synthesized tool_choice is never silently dropped here.
261	    let effective_tc = synth_tc.or(caller_tc);
262	
263	    // Validate forced tool choices on supported families.
264	    // (On unsupported families, forced choices were already omitted by translate_tool_choice.)
265	    if family.supports_forced_tool_choice() {
266	        match req.model_settings.tool_choice.as_ref() {
267	            Some(ToolChoice::Required) if !synthesizing => {
268	                if all_tools.is_empty() {
269	                    return Err(required_without_tools_error());
270	                }
271	            }
272	            Some(ToolChoice::Tool { name }) => check_tool_name(&all_tools, name)?,
273	            _ => {}
274	        }
275	    }
276	
277	    let tool_config = assemble_tool_config(all_tools, effective_tc)?;
278	
279	    // Build InferenceConfiguration.
280	    let inference_config = build_inference_config(req, cfg);
281	
282	    Ok(PreparedConverse {
283	        model_id: cfg.model_id.clone(),
284	        system: translated.system,
285	        messages: translated.messages,
286	        tool_config,
287	        inference_config,
288	        synthesizing,
289	        output_config: None,
290	        notices: Vec::new(),
291	    })
292	}
