349	// ── Wire-projection (snapshot tests) ─────────────────────────────────────────
350	
351	/// Project a [`PreparedConverse`] into a stable [`serde_json::Value`] for
352	/// snapshot tests.
353	///
354	/// This projection is deliberately **not** based on `Debug` output of the SDK
355	/// types, which can change across SDK version bumps. Instead, it is a hand-written
356	/// extraction of the semantically relevant fields.
357	#[cfg(test)]
358	pub(crate) fn to_wire_json(p: &PreparedConverse) -> serde_json::Value {
359	    use aws_sdk_bedrockruntime::types::{
360	        ContentBlock, SystemContentBlock, ToolChoice as SdkToolChoice, ToolResultContentBlock,
361	    };
362	    use serde_json::{json, Value};
363	
364	    // System blocks
365	    let system: Vec<Value> = p
366	        .system
367	        .iter()
368	        .map(|s| match s {
369	            SystemContentBlock::Text(t) => json!({"text": t}),
370	            _ => json!({"unknown": true}),
371	        })
372	        .collect();
373	
374	    // Messages
375	    let messages: Vec<Value> = p
376	        .messages
377	        .iter()
378	        .map(|m| {
379	            let role = match m.role {
380	                aws_sdk_bedrockruntime::types::ConversationRole::User => "user",
381	                aws_sdk_bedrockruntime::types::ConversationRole::Assistant => "assistant",
382	                _ => "unknown",
383	            };
384	            let content: Vec<Value> = m
385	                .content
386	                .iter()
387	                .map(|b| match b {
388	                    ContentBlock::Text(t) => json!({"text": t}),
389	                    ContentBlock::ToolUse(tu) => json!({
390	                        "toolUse": {
391	                            "toolUseId": tu.tool_use_id,
392	                            "name": tu.name,
393	                        }
394	                    }),
395	                    ContentBlock::ToolResult(tr) => {
396	                        let text_content = tr
397	                            .content
398	                            .iter()
399	                            .find_map(|c| {
400	                                if let ToolResultContentBlock::Text(t) = c {
401	                                    Some(t.as_str())
402	                                } else {
403	                                    None
404	                                }
405	                            })
406	                            .unwrap_or("");
407	                        json!({
408	                            "toolResult": {
409	                                "toolUseId": tr.tool_use_id,
410	                                "content": [{"text": text_content}],
411	                            }
412	                        })
413	                    }
414	                    _ => json!({"unknown": true}),
415	                })
416	                .collect();
417	            json!({"role": role, "content": content})
418	        })
419	        .collect();
420	
421	    // Tool config
422	    let tool_config: Value = match &p.tool_config {
423	        None => Value::Null,
424	        Some(tc) => {
425	            let tools: Vec<Value> = tc
426	                .tools()
427	                .iter()
428	                .map(|t| match t {
429	                    Tool::ToolSpec(spec) => {
430	                        let schema_placeholder = match spec.input_schema() {
431	                            Some(s) if s.is_json() => json!("<Document>"),
432	                            _ => Value::Null,
433	                        };
434	                        json!({
435	                            "toolSpec": {
436	                                "name": spec.name(),
437	                                "description": spec.description(),
438	                                "inputSchema": {"json": schema_placeholder},
439	                            }
440	                        })
441	                    }
442	                    _ => json!({"unknown": true}),
443	                })
444	                .collect();
445	            let tc_value: Value = match tc.tool_choice() {
446	                None => Value::Null,
447	                Some(SdkToolChoice::Auto(_)) => json!({"auto": {}}),
448	                Some(SdkToolChoice::Any(_)) => json!({"any": {}}),
449	                Some(SdkToolChoice::Tool(s)) => json!({"tool": {"name": s.name()}}),
450	                _ => json!({"unknown": true}),
451	            };
452	            json!({
453	                "tools": tools,
454	                "toolChoice": tc_value,
455	            })
456	        }
457	    };
458	
459	    // Inference config
460	    let inference_config: Value = match &p.inference_config {
461	        None => Value::Null,
462	        Some(ic) => {
463	            let mut m = serde_json::Map::new();
464	            if let Some(t) = ic.temperature() {
465	                m.insert("temperature".into(), json!(t));
466	            }
467	            if let Some(p) = ic.top_p() {
468	                m.insert("topP".into(), json!(p));
469	            }
470	            if let Some(mt) = ic.max_tokens() {
471	                m.insert("maxTokens".into(), json!(mt));
472	            }
473	            Value::Object(m)
474	        }
475	    };
476	
477	    let mut wire = json!({
478	        "modelId": p.model_id,
479	        "system": system,
480	        "messages": messages,
481	        "toolConfig": tool_config,
482	        "inferenceConfig": inference_config,
483	        "synthesizing": p.synthesizing,
484	    });
485	
486	    // Output config: the key is present only on the native path, so the
487	    // forced-tool snapshots do not change.
488	    if let Some(oc) = &p.output_config {
489	        let text_format = oc.text_format().map(|tf| {
490	            let structure = tf
491	                .structure()
492	                .and_then(|s| s.as_json_schema().ok())
493	                .map(|js| {
494	                    let schema: Value = serde_json::from_str(js.schema())
495	                        .expect("the native output schema is a JSON string");
496	                    json!({"jsonSchema": {"name": js.name(), "schema": schema}})
497	                });
498	            json!({"type": tf.r#type().as_str(), "structure": structure})
499	        });
500	        wire["outputConfig"] = json!({"textFormat": text_format});
501	    }
502	    wire
503	}
