1	//! [`BedrockModel`] — the Bedrock Converse API model handle.
2	//!
3	//! Wraps an `Arc<Config>` so that the model handle is `Clone + Send + Sync`
4	//! and the `BoxStream` returned by `invoke` can be `'static + Send`.
5	
6	use std::future::Future;
7	use std::sync::Arc;
8	
9	use async_stream::stream;
10	use async_trait::async_trait;
11	use futures_core::stream::BoxStream;
12	use paigasus_helikon_core::{
13	    CancellationToken, Model, ModelCapabilities, ModelError, ModelEvent, ModelRequest,
14	};
15	
16	use aws_sdk_bedrockruntime::operation::converse_stream::ConverseStreamOutput;
17	use aws_sdk_bedrockruntime::Client;
18	
19	use crate::builder::Config;
20	use crate::error::{map_sdk_error, send_failure, SendFailure};
21	use crate::fallback::{send_with_fallback, Sent};
22	use crate::policy::ForcedChoicePolicy;
23	use crate::stream::StreamTranslator;
24	use crate::translate::{build_request, PreparedConverse};
25	
26	// ── BedrockModel ──────────────────────────────────────────────────────────────
27	
28	/// An Amazon Bedrock Converse API model handle.
29	///
30	/// Construct via [`BedrockModel::converse`] (sync builder) or
31	/// [`BedrockModel::from_env`] (async, loads AWS config from the environment).
32	///
33	/// The handle is `Clone + Send + Sync` because it holds only `Arc` values.
34	/// Clones share the state that the handle learns at run time.
35	#[derive(Debug, Clone)]
36	pub struct BedrockModel {
37	    pub(crate) config: Arc<Config>,
38	    pub(crate) policy: Arc<ForcedChoicePolicy>,
39	}
40	
41	/// Send one `ConverseStream` request.
42	///
43	/// The error keeps the flag that tells the fallback whether the service
44	/// rejected a forced tool choice.
45	fn send_converse_stream(
46	    client: &Client,
47	    p: PreparedConverse,
48	) -> impl Future<Output = Result<ConverseStreamOutput, SendFailure>> {
49	    let fluent = client
50	        .converse_stream()
51	        .model_id(&p.model_id)
52	        .set_messages(Some(p.messages))
53	        .set_system(if p.system.is_empty() {
54	            None
55	        } else {
56	            Some(p.system)
57	        })
58	        .set_tool_config(p.tool_config)
59	        .set_inference_config(p.inference_config)
60	        .set_output_config(p.output_config);
61	    // fluent.send() returns SdkError<_, HttpResponse>, so send_failure can
62	    // read the Retry-After header.
63	    async move { fluent.send().await.map_err(send_failure) }
64	}
65	
66	// ── Model impl ────────────────────────────────────────────────────────────────
67	
68	#[async_trait]
69	impl Model for BedrockModel {
70	    /// Stream model events from Amazon Bedrock's Converse API.
71	    ///
72	    /// The returned stream is `'static + Send`.
73	    ///
74	    /// **Cancellation contract:** when `cancel` fires mid-stream, the stream
75	    /// ends immediately without emitting a final `Finish` event (per the core
76	    /// `Model` trait contract).
77	    async fn invoke(
78	        &self,
79	        request: ModelRequest,
80	        cancel: CancellationToken,
81	    ) -> Result<BoxStream<'static, Result<ModelEvent, ModelError>>, ModelError> {
82	        // Translate the core request into Bedrock wire format (early error on
83	        // translation failure — before we open any network connection).
84	        let first = build_request(&self.config, &request, self.policy.path())?;
85	
86	        let config = Arc::clone(&self.config);
87	        let policy = Arc::clone(&self.policy);
88	        let client = self.config.client.clone();
89	
90	        let s = stream! {
91	            // The rebuild closure owns the request. It makes the native
92	            // request if the service rejects the forced tool choice of the
93	            // first request.
94	            let rebuild_cfg = Arc::clone(&config);
95	            let rebuild = move |path| build_request(&rebuild_cfg, &request, path);
96	
97	            // Send the request (and the one fallback request, if any) and
98	            // obtain the event receiver. Guard with a cancellation check
99	            // (biased: cancel arm wins) so that a token already fired — or one
100	            // that fires during either HTTP send — aborts cleanly without
101	            // opening a dangling Bedrock stream and without emitting Finish
102	            // (per the Model::invoke cancellation contract).
103	            let sent = tokio::select! {
104	                biased;
105	                _ = cancel.cancelled() => { return; }
106	                result = send_with_fallback(
107	                    &policy,
108	                    &config.model_id,
109	                    first,
110	                    rebuild,
111	                    |p| send_converse_stream(&client, p),
112	                ) => result,
113	            };
114	            let Sent {
115	                output,
116	                synthesizing,
117	                native,
118	            } = match sent {
119	                Ok(sent) => sent,
120	                Err(e) => {
121	                    yield Err(e);
122	                    return;
123	                }
124	            };
