1	//! [`BedrockModel`] — the Bedrock Converse API model handle.
2	//!
3	//! Wraps an `Arc<Config>` so that the model handle is `Clone + Send + Sync`
4	//! and the `BoxStream` returned by `invoke` can be `'static + Send`.
5	
6	use std::future::Future;
7	use std::sync::Arc;
8	
9	use async_stream::stream;
10	use async_trait::async_trait;
11	use futures_core::stream::BoxStream;
12	use paigasus_helikon_core::{
13	    CancellationToken, Model, ModelCapabilities, ModelError, ModelEvent, ModelRequest,
14	};
15	
16	use aws_sdk_bedrockruntime::operation::converse_stream::ConverseStreamOutput;
17	use aws_sdk_bedrockruntime::Client;
18	
19	use crate::builder::Config;
20	use crate::error::{map_sdk_error, send_failure, SendFailure};
21	use crate::fallback::{send_with_fallback, Sent};
22	use crate::policy::ForcedChoicePolicy;
23	use crate::stream::StreamTranslator;
24	use crate::translate::{build_request, PreparedConverse};
25	
26	// ── BedrockModel ──────────────────────────────────────────────────────────────
27	
28	/// An Amazon Bedrock Converse API model handle.
29	///
30	/// Construct via [`BedrockModel::converse`] (sync builder) or
31	/// [`BedrockModel::from_env`] (async, loads AWS config from the environment).
32	///
33	/// The handle is `Clone + Send + Sync` because it holds only `Arc` values.
34	/// Clones share the state that the handle learns at run time.
35	#[derive(Debug, Clone)]
36	pub struct BedrockModel {
37	    pub(crate) config: Arc<Config>,
38	    pub(crate) policy: Arc<ForcedChoicePolicy>,
39	}
40	
41	/// Send one `ConverseStream` request.
42	///
43	/// The error keeps the flag that tells the fallback whether the service
44	/// rejected a forced tool choice.
45	fn send_converse_stream(
46	    client: &Client,
47	    p: PreparedConverse,
48	) -> impl Future<Output = Result<ConverseStreamOutput, SendFailure>> {
49	    let fluent = client
50	        .converse_stream()
51	        .model_id(&p.model_id)
52	        .set_messages(Some(p.messages))
53	        .set_system(if p.system.is_empty() {
54	            None
55	        } else {
56	            Some(p.system)
57	        })
58	        .set_tool_config(p.tool_config)
59	        .set_inference_config(p.inference_config)
60	        .set_output_config(p.output_config);
61	    // fluent.send() returns SdkError<_, HttpResponse>, so send_failure can
62	    // read the Retry-After header.
63	    async move { fluent.send().await.map_err(send_failure) }
64	}
65	
66	// ── Model impl ────────────────────────────────────────────────────────────────
67	
68	#[async_trait]
69	impl Model for BedrockModel {
70	    /// Stream model events from Amazon Bedrock's Converse API.
71	    ///
72	    /// The returned stream is `'static + Send`.
73	    ///
74	    /// **Cancellation contract:** when `cancel` fires mid-stream, the stream
75	    /// ends immediately without emitting a final `Finish` event (per the core
76	    /// `Model` trait contract).
77	    async fn invoke(
78	        &self,
79	        request: ModelRequest,
80	        cancel: CancellationToken,
81	    ) -> Result<BoxStream<'static, Result<ModelEvent, ModelError>>, ModelError> {
82	        // Translate the core request into Bedrock wire format (early error on
83	        // translation failure — before we open any network connection).
84	        let first = build_request(&self.config, &request, self.policy.path())?;
85	
86	        let config = Arc::clone(&self.config);
87	        let policy = Arc::clone(&self.policy);
88	        let client = self.config.client.clone();
89	
90	        let s = stream! {
91	            // The rebuild closure owns the request. It makes the native
92	            // request if the service rejects the forced tool choice of the
93	            // first request.
94	            let rebuild_cfg = Arc::clone(&config);
95	            let rebuild = move |path| build_request(&rebuild_cfg, &request, path);
96	
97	            // Send the request (and the one fallback request, if any) and
98	            // obtain the event receiver. Guard with a cancellation check
99	            // (biased: cancel arm wins) so that a token already fired — or one
100	            // that fires during either HTTP send — aborts cleanly without
101	            // opening a dangling Bedrock stream and without emitting Finish
102	            // (per the Model::invoke cancellation contract).
103	            let sent = tokio::select! {
104	                biased;
105	                _ = cancel.cancelled() => { return; }
106	                result = send_with_fallback(
107	                    &policy,
108	                    &config.model_id,
109	                    first,
110	                    rebuild,
111	                    |p| send_converse_stream(&client, p),
112	                ) => result,
113	            };
114	            let Sent {
115	                output,
116	                synthesizing,
117	                native,
118	            } = match sent {
119	                Ok(sent) => sent,
120	                Err(e) => {
121	                    yield Err(e);
122	                    return;
123	                }
124	            };
125	
126	            let mut receiver = output.stream;
127	            let mut translator = StreamTranslator::new(synthesizing).native(native);
128	
129	            loop {
130	                let next = tokio::select! {
131	                    biased;
132	                    _ = cancel.cancelled() => {
133	                        // Cancellation: end stream without emitting Finish.
134	                        return;
135	                    }
136	                    r = receiver.recv() => r,
137	                };
138	
139	                match next {
140	                    // Stream exhausted normally (EOF).
141	                    // Flush any buffered stop reason that arrived without a
142	                    // subsequent Metadata event so the consumer always sees
143	                    // a terminal Finish.
144	                    Ok(None) => {
145	                        if let Some(terminal) = translator.finish() {
146	                            yield terminal;
147	                        }
148	                        return;
149	                    }
150	                    // Good event — feed through translator and yield results.
151	                    Ok(Some(event)) => {
152	                        for result in translator.consume(event) {
153	                            yield result;
154	                        }
155	                    }
156	                    // Transport-level error on the event stream.
157	                    Err(e) => {
158	                        yield Err(map_sdk_error(e));
159	                        return;
160	                    }
161	                }
162	            }
163	        };
164	
165	        Ok(Box::pin(s))
166	    }
167	
168	    fn capabilities(&self) -> ModelCapabilities {
169	        self.config.capabilities
170	    }
171	
172	    fn provider(&self) -> &str {
173	        "bedrock"
174	    }
175	
176	    fn model(&self) -> &str {
177	        &self.config.model_id
178	    }
179	}
180	
181	// ── Unit tests (descriptor + capability + cancellation contract) ──────────────
182	
183	#[cfg(test)]
184	mod tests {
185	    use super::*;
186	    use aws_config::{BehaviorVersion, Region};
187	    use futures_core::stream::BoxStream;
188	
189	    // ── Cancellation-wrapper helper (test-only) ───────────────────────────────
190	
191	    /// Wrap any `Stream<Item = Result<ModelEvent, ModelError>>` with a
192	    /// `CancellationToken` guard.
193	    ///
194	    /// When `cancel` fires, the returned stream ends immediately **without**
195	    /// emitting a `Finish` event — matching the `Model::invoke` cancellation
196	    /// contract.
197	    fn drive_stream_with_token<S>(
198	        source: S,
199	        cancel: CancellationToken,
200	    ) -> BoxStream<'static, Result<ModelEvent, ModelError>>
201	    where
202	        S: futures_core::Stream<Item = Result<ModelEvent, ModelError>> + Send + 'static,
203	    {
204	        Box::pin(stream! {
205	            tokio::pin!(source);
206	            loop {
207	                let next = tokio::select! {
208	                    biased;
209	                    _ = cancel.cancelled() => return,
210	                    r = futures_util::StreamExt::next(&mut source) => r,
211	                };
212	                match next {
213	                    None => return,
214	                    Some(v) => yield v,
215	                }
216	            }
217	        })
218	    }
219	
220	    fn offline_model(model_id: &str) -> BedrockModel {
221	        let rt = tokio::runtime::Builder::new_current_thread()
222	            .enable_all()
223	            .build()
224	            .expect("tokio runtime");
225	        rt.block_on(async {
226	            let sdk_cfg = aws_config::defaults(BehaviorVersion::v2026_11_17())
227	                .region(Region::new("us-east-1"))
228	                .test_credentials()
229	                .load()
230	                .await;
231	            BedrockModel::converse(model_id)
232	                .sdk_config(&sdk_cfg)
233	                .build()
234	                .expect("build offline model")
235	        })
236	    }
237	
238	    #[test]
239	    fn clones_share_the_policy() {
240	        let m = offline_model("anthropic.claude-3-5-sonnet-20241022-v2:0");
241	        let m2 = m.clone();
242	        assert!(m.policy.record_rejection());
243	        assert_eq!(m2.policy.path(), crate::policy::OutputPath::Native);
244	        let fresh = offline_model("anthropic.claude-3-5-sonnet-20241022-v2:0");
245	        assert_eq!(fresh.policy.path(), crate::policy::OutputPath::ForcedTool);
246	    }
247	
248	    // `offline_model` blocks on its own runtime, so this test is a plain
249	    // `#[test]` that drives `invoke` on a second runtime.
250	    #[test]
251	    fn invoke_rejects_blank_only_request_before_network() {
252	        let m = offline_model("anthropic.claude-3-5-sonnet-20241022-v2:0");
253	        let mut req = ModelRequest::new();
254	        req.messages = vec![paigasus_helikon_core::Item::UserMessage {
255	            content: vec![paigasus_helikon_core::ContentPart::Text {
256	                text: String::new(),
257	            }],
258	        }];
259	        let rt = tokio::runtime::Builder::new_current_thread()
260	            .enable_all()
261	            .build()
262	            .expect("tokio runtime");
263	        let res = rt.block_on(m.invoke(req, CancellationToken::new()));
264	        match res {
