//! ```sh
//! BEDROCK_MODEL_ID=global.anthropic.claude-sonnet-4-5-20250929-v1:0 \
//! AWS_DEFAULT_REGION=us-east-1 \
//! cargo test -p paigasus-helikon-providers-bedrock -- --ignored
//! ```
//!
//! ## Native structured-output tests (SMA-839)
//!
//! Run only these against Claude Sonnet 5.5 with the dev profile:
//! ```sh
//! AWS_PROFILE=maip-dev-admin AWS_DEFAULT_REGION=us-east-1 \
//! BEDROCK_MODEL_ID=global.anthropic.claude-sonnet-5-5 \
//! cargo test -p paigasus-helikon-providers-bedrock native_output_schemars_style_schema \
//!   -- --ignored --nocapture
//! # also: structured_output_finalizing_turn_after_tool_round
//! # and, in the lib target: live_rule_b_learns_native_output_after_rejection
//! ```
//!
//! ## Required environment variables
//!
//! | Variable | Description |
//! |---|---|
//! | `BEDROCK_MODEL_ID` | Bedrock model id to test against |
//! | `AWS_DEFAULT_REGION` | (or `AWS_REGION`) — AWS region |
//! | AWS credentials | Any standard AWS credential chain value |
//!
//! When any required variable is unset the test prints a loud skip message and
//! returns early (the test passes so CI stays green).

use futures_util::StreamExt;
use paigasus_helikon_core::{
    CancellationToken, ContentPart, Item, Model, ModelEvent, ModelRequest, ResponseFormat, ToolDef,
};
use paigasus_helikon_providers_bedrock::BedrockModel;

// ── helpers ───────────────────────────────────────────────────────────────────

fn skip_if_missing_env() -> Option<String> {
    let model_id = match std::env::var("BEDROCK_MODEL_ID") {
        Ok(v) if !v.is_empty() => v,
        _ => {
            eprintln!(
                "[live] BEDROCK_MODEL_ID not set — skipping live Bedrock test. \
                 Set BEDROCK_MODEL_ID, AWS_DEFAULT_REGION, and AWS credentials to run."
            );
            return None;
        }
    };
    Some(model_id)
}

fn user(s: &str) -> Item {
    Item::UserMessage {
        content: vec![ContentPart::Text { text: s.to_owned() }],
    }
}

fn assistant(s: &str) -> Item {
    Item::AssistantMessage {
        content: vec![ContentPart::Text { text: s.to_owned() }],
        agent: None,
    }
}

fn tool_call(call_id: &str, name: &str) -> Item {
    Item::ToolCall {
        call_id: call_id.to_owned(),
        name: name.to_owned(),
        args: serde_json::json!({}),
    }
}

fn tool_result(call_id: &str, text: &str) -> Item {
    Item::ToolResult {
        call_id: call_id.to_owned(),
        content: vec![ContentPart::Text {
            text: text.to_owned(),
        }],
    }
}

fn ping_tool() -> ToolDef {
    ToolDef::new(
        "ping",
        "Ping a host",
        serde_json::json!({"type": "object", "properties": {}}),
    )
}

/// Send `messages` (with optional `tools`) and assert the stream ends with no
/// `Err` event and carries at least one `TokenDelta` or `Finish` event.
async fn send_and_assert_ok(model_id: &str, messages: Vec<Item>, tools: Vec<ToolDef>) {
    let model = BedrockModel::from_env(model_id)
        .await
        .expect("from_env should succeed");

    let mut req = ModelRequest::new();
    req.messages = messages;
    req.tools = tools;
    req.model_settings.max_output_tokens = Some(64);

    let mut s = model
        .invoke(req, CancellationToken::new())
        .await
        .expect("invoke should succeed");

    let mut had_error = false;
    let mut saw_output = false;
    while let Some(ev) = s.next().await {
        match ev {
            Ok(ModelEvent::TokenDelta { .. } | ModelEvent::Finish { .. }) => saw_output = true,
            Ok(_) => {}
            Err(e) => {
                eprintln!("[live] stream error: {e:?}");
                had_error = true;
            }
        }
    }
    assert!(!had_error, "stream must complete without error");
    assert!(saw_output, "stream must carry a TokenDelta or Finish event");
}

