86	/// A failed send, with the flag that the fallback reads.
87	#[derive(Debug)]
88	pub(crate) struct SendFailure {
89	    /// `true` when the service rejected a forced tool choice.
90	    pub(crate) forced_choice_rejected: bool,
91	    /// The mapped error that goes to the caller when no fallback occurs.
92	    pub(crate) error: ModelError,
93	}
94	
95	/// Parse the `Retry-After` header (integer seconds) from Bedrock response headers into milliseconds.
96	///
97	/// Returns `None` when the header is absent or its value is not a non-negative integer
98	/// (HTTP-date retry-after values are not supported — `None` is the safe fallback).
99	pub(crate) fn parse_retry_after_ms(headers: &Headers) -> Option<u64> {
100	    headers
101	        .get("retry-after")
102	        .and_then(|v| v.trim().parse::<u64>().ok())
103	        .map(|seconds| seconds.saturating_mul(1000))
104	}
105	
106	/// Map a Bedrock SDK [`SdkError`] to a [`ModelError`].
107	///
108	/// For `ServiceError`, the modeled error code and message are extracted via
109	/// [`ProvideErrorMetadata`] and delegated to [`classify`]. Transport-level
110	/// failures (`DispatchFailure`, `TimeoutError`, `ConstructionFailure`,
111	/// `ResponseError`) map to [`ModelError::Transport`].
112	///
113	/// This generic variant does **not** inspect HTTP headers (the response type `R`
114	/// may not be an HTTP response — e.g. the event-stream `recv()` path produces
115	/// `SdkError<_, RawMessage>`). Call [`map_sdk_http_error`] when `R` is known to
116	/// be [`aws_smithy_runtime_api::http::Response`] and you want `Retry-After`
117	/// header extraction.
118	pub(crate) fn map_sdk_error<E, R>(err: SdkError<E, R>) -> ModelError
119	where
120	    E: ProvideErrorMetadata + std::fmt::Debug,
121	    R: std::fmt::Debug,
122	{
123	    match &err {
124	        SdkError::ServiceError(svc) => {
125	            let code = svc.err().code();
126	            let message = svc.err().message().unwrap_or("");
127	            classify(code, None, message, None)
128	        }
129	        SdkError::DispatchFailure(_)
130	        | SdkError::TimeoutError(_)
131	        | SdkError::ConstructionFailure(_)
132	        | SdkError::ResponseError(_) => ModelError::Transport(format!("{err:?}")),
133	        // Non-exhaustive: treat any future variant as transport.
134	        _ => ModelError::Transport(format!("{err:?}")),
135	    }
136	}
137	
138	/// Map a Bedrock SDK [`SdkError`] whose response type is the concrete HTTP
139	/// response to a [`ModelError`], extracting `Retry-After` header and HTTP
140	/// status from the raw response.
141	///
142	/// This is the preferred variant for the initial `fluent.send()` call on a
143	/// Bedrock operation, where the SDK returns
144	/// `SdkError<E, aws_smithy_runtime_api::client::orchestrator::HttpResponse>`.
145	pub(crate) fn map_sdk_http_error<E>(
146	    err: SdkError<E, aws_smithy_runtime_api::http::Response>,
147	) -> ModelError
148	where
149	    E: ProvideErrorMetadata + std::fmt::Debug,
150	{
151	    match &err {
152	        SdkError::ServiceError(svc) => {
153	            let code = svc.err().code();
154	            let message = svc.err().message().unwrap_or("");
155	            let raw = svc.raw();
156	            let status = Some(raw.status().as_u16());
157	            let retry_after_ms = parse_retry_after_ms(raw.headers());
